// GetReadingHistory handles reading history requests.
func (h *SensorHandler) GetReadingHistory(ctx context.Context, req *connect.Request[pb.GetReadingHistoryRequest]) (*connect.Response[pb.GetReadingHistoryResponse], error) {
	if req.Msg.GetSensorId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "sensor_id is required")
	}

	var start, end time.Time
	if req.Msg.GetStartTime() != nil {
		start = req.Msg.GetStartTime().AsTime()
	}
	if req.Msg.GetEndTime() != nil {
		end = req.Msg.GetEndTime().AsTime()
	}

	minQuality := ""
	if req.Msg.GetMinQuality() != pb.ReadingQuality_READING_QUALITY_UNSPECIFIED {
		minQuality = string(readingQualityFromProto(req.Msg.GetMinQuality()))
	}

	readings, total, err := h.svc.GetReadingHistory(ctx, req.Msg.GetSensorId(), start, end, minQuality, req.Msg.GetPageSize(), req.Msg.GetPageOffset())
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	protos := make([]*pb.SensorReading, 0, len(readings))
	for i := range readings {
		protos = append(protos, sensorReadingToProto(&readings[i]))
	}
	return connect.NewResponse(&pb.GetReadingHistoryResponse{
		Readings:   protos,
		TotalCount: total,
	}), nil
}

